import numpy as np


def r(x):
    # Monotonic transformation: for x in [0, 1], sqrt(x) >= x.
    # This shifts the input to a larger value within the same domain.
    return float(np.sqrt(x))


def R(y_orig, y_new):
    # For a monotonic increasing function, y_new must be greater than or equal to y_orig.
    return bool(np.isfinite(y_orig) and np.isfinite(y_new) and y_new >= y_orig)
